/* eslint-disable space-in-parens */

import zeros = require( '@stdlib/ndarray/zeros' );
import dspmv = require( '@stdlib/blas/base/ndarray/dspmv' );


// TESTS //

// The function returns an ndarray...
{
	const AP = zeros( [ 6 ], {
		'dtype': 'float64'
	});
	const x = zeros( [ 3 ], {
		'dtype': 'float64'
	});
	const y = zeros( [ 3 ], {
		'dtype': 'float64'
	});
	const uplo = zeros( [], {
		'dtype': 'int32'
	});
	const alpha = zeros( [], {
		'dtype': 'float64'
	});
	const beta = zeros( [], {
		'dtype': 'float64'
	});

	dspmv( [ AP, x, y, uplo, alpha, beta ] ); // $ExpectType float64ndarray
}

// The compiler throws an error if the function is provided a first argument which is not an array of ndarrays...
{
	dspmv( '10' ); // $ExpectError
	dspmv( 10 ); // $ExpectError
	dspmv( true ); // $ExpectError
	dspmv( false ); // $ExpectError
	dspmv( null ); // $ExpectError
	dspmv( undefined ); // $ExpectError
	dspmv( [] ); // $ExpectError
	dspmv( {} ); // $ExpectError
	dspmv( ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const AP = zeros( [ 6 ], {
		'dtype': 'float64'
	});
	const x = zeros( [ 3 ], {
		'dtype': 'float64'
	});
	const y = zeros( [ 3 ], {
		'dtype': 'float64'
	});
	const uplo = zeros( [], {
		'dtype': 'int32'
	});
	const alpha = zeros( [], {
		'dtype': 'float64'
	});
	const beta = zeros( [], {
		'dtype': 'float64'
	});

	dspmv(); // $ExpectError
	dspmv( [ AP, x, y, uplo, alpha, beta ], {} ); // $ExpectError
}
